package br.edu.ifms.robotica.servlet;
import java.io.IOException;import java.sql.SQLException;import java.util.List;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import br.edu.ifms.robotica.dao.*;import br.edu.ifms.robotica.model.Atividade;
@WebServlet("/admin/relatorio-periodo") public class RelatorioPeriodoServlet extends HttpServlet{private final AtividadeDAO atividadeDAO=new AtividadeDAO();private final ParticipacaoDAO participacaoDAO=new ParticipacaoDAO();private final ConquistaDAO conquistaDAO=new ConquistaDAO();
 @Override protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{String ano=r.getParameter("ano"),sem=r.getParameter("semestre");try{if(ano!=null&&!ano.isBlank()&&sem!=null&&!sem.isBlank()){int a=Integer.parseInt(ano),s=Integer.parseInt(sem);if(s<1||s>2)throw new NumberFormatException();List<Atividade> atividades=atividadeDAO.listarPorPeriodo(a,s);for(Atividade x:atividades){x.setParticipacoes(participacaoDAO.listarPorAtividade(x.getId()));x.setConquistas(conquistaDAO.listarPorAtividade(x.getId()));}r.setAttribute("atividades",atividades);r.setAttribute("consultado",true);}r.getRequestDispatcher("/WEB-INF/views/admin/relatorio-periodo.jsp").forward(r,p);}catch(NumberFormatException e){r.setAttribute("erro","erro.periodo.invalido");r.getRequestDispatcher("/WEB-INF/views/admin/relatorio-periodo.jsp").forward(r,p);}catch(SQLException e){throw new ServletException(e);}}
}
